import * as ui from "std/ui"

@jsonable
class LogEntry {
  guess: number;
  minute: number;
}

@jsonable
class AppState {
  upperBoundText: string;
  entries: LogEntry[];
  draft_guess: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {upperBoundText: "100", entries: emptyEntries, draft_guess: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_upperBound(state: AppState, value: string): AppState {
  return {upperBoundText: value, entries: state.entries, draft_guess: state.draft_guess, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_guess(state: AppState, value: string): AppState {
  return {draft_guess: value, upperBoundText: state.upperBoundText, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_guess) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {guess: strings.toNumber(state.draft_guess, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_guess: "", upperBoundText: state.upperBoundText, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, upperBoundText: state.upperBoundText, draft_guess: state.draft_guess};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, upperBoundText: state.upperBoundText, draft_guess: state.draft_guess};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, upperBoundText: state.upperBoundText, entries: state.entries, draft_guess: state.draft_guess};
}





function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Guess the Number", "NUMBER GAME", "Pick a range, guess, and get told higher or lower.", ""));
  {
      let upperBound: number = strings.toNumber(state.upperBoundText, 0);
      let maxGuesses: number = 10;
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.guess; }
      let guessesLeft: number = maxGuesses - entryCount;
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Highest number", state.upperBoundText, "set_upperBound", "number")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Guesses left", guessesLeft, "", "", 1, "", "chart", 0)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", ui.formatNumber(e.guess, 0), sub, "", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Your guess", state.draft_guess, "set_draft_guess", "number"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_guess) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Guesses", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  return ui.AppTheme("playful", "", sections);
}

