function c_upper(state: AppState): number {
  let u: number = math.floor(strings.toNumber(state.upperBoundText, 0));
  if (u < 2) { return 0; }
  if (u > 1000000) { return 1000000; }
  return u;
}

function c_newSecret(state: AppState, upper: number): number {
  let seed: number = time.nowMillis() + state.entries.length() * 7919 + state.c_round * 104729;
  return math.randomBelow(seed, upper) + 1;
}

function c_start(state: AppState, ignored: number): AppState {
  let upper: number = c_upper(state);
  if (upper < 2) { return {c_feedback: "Set a highest number of 2 or more first.", c_feedbackTone: "warning", c_feedbackTrigger: state.c_feedbackTrigger + 1__PASSTHROUGH__}; }
  let secret: number = c_newSecret(state, upper);
  return {c_secret: secret, c_secretUpper: upper, c_round: state.c_round + 1, c_feedback: "A secret number between 1 and " + ui.numberToString(upper) + " is set. Make your guess.", c_feedbackTone: "accent", c_feedbackTrigger: state.c_feedbackTrigger + 1, c_won: false, c_lost: false__PASSTHROUGH__};
}

function c_guess(state: AppState, ignored: number): AppState {
  if (state.c_secretUpper === 0) { return state; }
  if (state.c_won || state.c_lost) { return state; }
  if (strings.trim(state.draft_guess) === "") { return state; }
  let g: number = math.floor(strings.toNumber(state.draft_guess, 0));
  if (g < 1 || g > state.c_secretUpper) {
    return {c_feedback: "Enter a whole number from 1 to " + ui.numberToString(state.c_secretUpper) + ".", c_feedbackTone: "warning", c_feedbackTrigger: state.c_feedbackTrigger + 1__PASSTHROUGH__};
  }
  let entry: LogEntry = {guess: g, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
