  out.push(entry);
  let maxGuesses: number = 10;
  let used: number = out.length();
  if (g === state.c_secret) {
    return {entries: out, draft_guess: "", c_won: true, c_lost: false, c_feedback: "Correct! The secret was " + ui.numberToString(state.c_secret) + ". You found it in " + ui.numberToString(used) + " guess" + (used === 1 ? "" : "es") + ".", c_feedbackTone: "success", c_feedbackTrigger: state.c_feedbackTrigger + 1__PASSTHROUGH__};
  }
  if (used >= maxGuesses) {
    return {entries: out, draft_guess: "", c_won: false, c_lost: true, c_feedback: "Out of guesses. The secret was " + ui.numberToString(state.c_secret) + ".", c_feedbackTone: "danger", c_feedbackTrigger: state.c_feedbackTrigger + 1__PASSTHROUGH__};
  }
  let hint: string = "";
  if (state.c_secret > g) { hint = "Higher than " + ui.numberToString(g) + "."; } else { hint = "Lower than " + ui.numberToString(g) + "."; }
  return {entries: out, draft_guess: "", c_feedback: hint, c_feedbackTone: "accent", c_feedbackTrigger: state.c_feedbackTrigger + 1__PASSTHROUGH__};
}
