function c_shuffle(state: AppState, size: number): AppState {
  let syms: string[] = c_symbols();
  let deck: string[] = [];
  let i: number = 0;
  while (i < syms.length()) {
    deck.push(syms[i]);
    i = i + 1;
  }
  let seed: number = state.c_seed;
  let n: number = deck.length();
  let j: number = n - 1;
  while (j > 0) {
    seed = math.randomStep(seed);
    let k: number = math.randomBelow(seed, j + 1);
    let tmp: string = deck[j];
    deck[j] = deck[k];
    deck[k] = tmp;
    j = j - 1;
  }
  return {c_deck: deck, c_deckIndex: 0, c_flipped: false, c_roundSize: size, c_seed: seed, c_roundDone: false__PASSTHROUGH__};
}

