@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  rounds: number;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, rounds: 5};
}

function countdownSeconds(state: AppState): number {
  let rounds: number = state.rounds;
  let wordsPerRound: number = 4;
  let secondsPerRound: number = 30;
  return secondsPerRound;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, rounds: state.rounds}; }
  return {elapsedMs: total, running: false, finished: true, rounds: state.rounds};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, rounds: state.rounds};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, rounds: state.rounds};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, rounds: state.rounds};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



