function c_makeProblem(state: AppState, seed: number): AppState {
  let s: number = seed;
  let diff: number = state.difficultyIndex;
  let maxN: number = 10;
  if (diff === 1) { maxN = 20; }
  if (diff === 2) { maxN = 50; }
  let opCount: number = 2;
  if (diff === 1) { opCount = 3; }
  if (diff === 2) { opCount = 4; }
  let a: number = math.randomBelow(s, maxN) + 1;
  s = math.randomStep(s);
  let b: number = math.randomBelow(s, maxN) + 1;
  s = math.randomStep(s);
  let op: number = math.randomBelow(s, opCount);
  s = math.randomStep(s);
  if (op === 2) {
    if (b > a) { let t: number = a; a = b; b = t; }
    if (b === 0) { b = 1; }
  }
  if (op === 3) {
    if (b === 0) { b = 1; }
    a = b * (math.randomBelow(s, 10) + 1);
    s = math.randomStep(s);
  }
  return {c_problemA: a, c_problemB: b, c_problemOp: op, c_answerText: "", c_seed: s__PASSTHROUGH__};
}

function c_answerOf(a: number, b: number, op: number): number {
  if (op === 0) { return a + b; }
  if (op === 1) { return a - b; }
  if (op === 2) { return a * b; }
  if (b === 0) { return 0; }
  return a / b;
}

function c_opText(op: number): string {
  if (op === 0) { return "+"; }
  if (op === 1) { return "−"; }
  if (op === 2) { return "×"; }
  return "÷";
}

