    let fresh: AppState = c_makeProblem(state, state.c_seed);
    return {c_correct: 0, c_wrong: 0, c_attempted: 0, c_score: 0, c_flash: 0, c_answerText: "", c_problemA: fresh.c_problemA, c_problemB: fresh.c_problemB, c_problemOp: fresh.c_problemOp, c_seed: fresh.c_seed, c_lastElapsed: state.elapsedMs, c_prevRunning: state.running, c_wasFinished: state.finished__PASSTHROUGH__};
  }
  return {c_lastElapsed: state.elapsedMs, c_prevRunning: state.running, c_wasFinished: state.finished__PASSTHROUGH__};
}

